mapper.select:
SELECT name, value, 0 AS compare -- 类型(收/退),金额,同比(恒0)
FROM (
    SELECT '收' AS name, NVL(SUM(payment_amount), 0) AS value, 1 AS ord FROM tr_settle_payments -- 收金额
    WHERE stat_date BETWEEN #{startDate} AND #{endDate} AND money_type = #{moneyType}
    UNION ALL
    SELECT '退' AS name, NVL(SUM(refunded_amount), 0) AS value, 2 AS ord FROM tr_settle_payments -- 退金额
    WHERE stat_date BETWEEN #{startDate} AND #{endDate} AND money_type = #{moneyType}
)
ORDER BY ord
